! fx_behavior.f90 — port of racket/behavior.rkt: the deterministic PDF-derived behavior report
! (behavior-report.json + behavior-report.md) for a normalized transcript.json.
!
! Output is byte-identical to racket/behavior.rkt (analyze-transcript, report-json-string,
! render-markdown).  Semantics reproduced from Racket 9.3, measured rather than assumed:
!   * strings are UTF-8 bytes here; every offset, length and regex runs on code points;
!   * the regexes run on a small backtracking matcher (leftmost-first, like Racket pregexp):
!     \s = [ \t\n\f\r] (no \v), \b = ASCII word boundary ([A-Za-z0-9_]), "." matches newline,
!     (?i:) folds ASCII letters only (no non-ASCII character matches an ASCII letter);
!   * char-whitespace? = Unicode White_Space (table below);
!   * string-normalize-nfkc + string-downcase, as used by token-list / normalize-text, are
!     reproduced only to the extent they decide the [a-z0-9'] tokens: compatibility
!     decompositions that yield token characters, canonical reordering and composition that
!     swallow an ASCII letter into a precomposed letter, and U+0130 -> "i" + U+0307.  The tables
!     were generated from Racket's own normalizer (all 1,112,064 scalar values).
!   * floats print as Racket CS number->string (shortest round-trip digits, fixed notation for
!     decimal exponents -3..max(14, digits+3), otherwise d.ddde+XX); round is round-half-even.
module fx_behavior
  use iso_fortran_env, only: int64, real64
  use fx_util
  use fx_json
  implicit none
  private

  public :: BEHAVIOR_SCHEMA_VERSION, BEHAVIOR_DETECTOR_VERSION
  public :: behavior_str, behavior_result, behavior_analyze, behavior_write_summary, &
            behavior_write_manifest_record, behavior_normalize_text, behavior_token_list

  character(len=*), parameter :: BEHAVIOR_SCHEMA_VERSION = '1.0'
  character(len=*), parameter :: BEHAVIOR_DETECTOR_VERSION = 'pdf-behavior-reference-1.1.0'

  type :: behavior_str
     character(len=:), allocatable :: s
  end type behavior_str

  type :: behavior_result
     logical :: ok = .false.
     character(len=:), allocatable :: error      ! exn-message text when ok is false
     character(len=:), allocatable :: json       ! behavior-report.json contents (report-json-string)
     character(len=:), allocatable :: markdown   ! behavior-report.md contents (render-markdown)
     integer :: confirmed = 0, candidate = 0, not_assessable = 0, finding_count = 0
     integer :: ncategories = 0
     type(behavior_str), allocatable :: category_names(:)   ! summary.byCategory keys, sorted
     integer, allocatable :: category_counts(:)
  end type behavior_result

